import{_ as e,a as o,b as a,c as i,d as s}from"./chunks/workshop-modal-replenish.BFUqmCRb.js";import{_ as n,I as r,g as l,j as u}from"./chunks/framework.CjoWWfVe.js";const k=JSON.parse('{"title":"Workshop (Assets)","description":"Equipment and tool tracking, along with depreciation calculations, in OmniCraft ERP. Transforming expenses into investments.","frontmatter":{"title":"Workshop (Assets)","description":"Equipment and tool tracking, along with depreciation calculations, in OmniCraft ERP. Transforming expenses into investments.","order":4},"headers":[],"relativePath":"docs/spaces/production/workshop.md","filePath":"docs/spaces/production/workshop.md"}'),c={name:"docs/spaces/production/workshop.md"};function d(p,t,g,h,q,m){return r(),l("div",null,[...t[0]||(t[0]=[u('<h1 id="workshop-assets-equipment-tracking" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg> Workshop: Assets &amp; Equipment Tracking <a class="header-anchor" href="#workshop-assets-equipment-tracking" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z&quot;/&gt;&lt;/svg&gt; Workshop: Assets &amp; Equipment Tracking&quot;">​</a></h1><figure class="doc-image"><img src="'+e+'" alt="Main window of the Workshop tab"><figcaption>Main window of the Workshop tab</figcaption></figure><p>The <strong>&quot;Workshop&quot;</strong> tab is the registry of your manufacturing property. This is not just an inventory list of items sitting in your room. This section manages tangible assets that form a significant part of your business value (Capital).</p><p>Here, you manage machinery, high-value tools, electronics, consumables, and premises used in your workflow.</p><hr><h2 id="economic-rationale-transforming-expenses-into-capital" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3h12l4 6-10 13L2 9Z"></path><path d="M11 3 8 9l4 13"></path><path d="M13 3l3 6-4 13"></path><path d="M2 9h20"></path></svg> Economic Rationale: Transforming Expenses into Capital <a class="header-anchor" href="#economic-rationale-transforming-expenses-into-capital" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M6 3h12l4 6-10 13L2 9Z&quot;/&gt;&lt;path d=&quot;M11 3 8 9l4 13&quot;/&gt;&lt;path d=&quot;M13 3l3 6-4 13&quot;/&gt;&lt;path d=&quot;M2 9h20&quot;/&gt;&lt;/svg&gt; Economic Rationale: Transforming Expenses into Capital&quot;">​</a></h2><p>In professional managerial accounting, the purchase of expensive equipment is viewed differently than everyday household spending. OmniCraft ERP relies on two foundational economic rules:</p><ol><li><strong>Capital preservation upon purchase.</strong> Buying a laser engraver or a muffle furnace does not make you poorer. You simply transfer value from &quot;liquid cash&quot; into &quot;productive equipment.&quot; Your business capital remains unchanged—only its internal structure shifts.</li><li><strong>Depreciation without complex routine.</strong> Unlike heavy industrial systems requiring you to calculate machine-hours and log the operating time of every single drill, OmniCraft ERP takes a lean approach: <ul><li>The program automatically calculates and displays the <strong>total exact monthly depreciation of your entire workshop</strong> on the statistics panel.</li><li>Relying on this figure and your average production volume, you can establish an averaged global overhead norm under Settings.</li><li>In the Calculator, this norm can be adjusted via multipliers for each product. Thus, equipment costs are gradually recovered when selling finished products.</li></ul></li></ol><hr><h2 id="operating-modes-property-consumables" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg> Operating Modes: Property &amp; Consumables <a class="header-anchor" href="#operating-modes-property-consumables" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;polygon points=&quot;12 2 2 7 12 12 22 7 12 2&quot;/&gt;&lt;polyline points=&quot;2 17 12 22 22 17&quot;/&gt;&lt;polyline points=&quot;2 12 12 17 22 12&quot;/&gt;&lt;/svg&gt; Operating Modes: Property &amp; Consumables&quot;">​</a></h2><p>The table interface is divided into two independent tabs, switched via the top panel. Each tab features dedicated column visibility settings and filters.</p><h3 id="_1-property" tabindex="-1">1. Property <a class="header-anchor" href="#_1-property" aria-label="Permalink to &quot;1. Property&quot;">​</a></h3><p>The primary registry of long-term assets. This includes machinery, furniture, and tools engineered for multi-year service. For these items, specifying a lifespan is required, allowing the software to compute monthly depreciation and gradual residual value reduction.</p><h3 id="_2-consumables" tabindex="-1">2. Consumables <a class="header-anchor" href="#_2-consumables" aria-label="Permalink to &quot;2. Consumables&quot;">​</a></h3><p>The registry of fast-wearing supplies and auxiliary items (e.g., milling bits, drill bits, craft chemicals, brushes). The core difference is that consumables <strong>are not depreciated</strong>. Their entire purchase cost is immediately written off as a business expense (in the Cash Flow Ledger) at the moment of acquisition. Lifespans are not assigned to consumables, as their value transfers into production immediately.</p><hr><h2 id="practical-guide-where-to-begin" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg> Practical Guide: Where to Begin? <a class="header-anchor" href="#practical-guide-where-to-begin" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z&quot;/&gt;&lt;path d=&quot;M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z&quot;/&gt;&lt;/svg&gt; Practical Guide: Where to Begin?&quot;">​</a></h2><p>When initially setting up your database, common questions arise: what date to choose for older equipment, how to evaluate gifts, and what lifespan to set.</p><p>Below is a quick cheat sheet and real-world production cases to help you configure your workshop assets with confidence.</p><h3 id="craftsman-s-cheat-sheet-guidelines-for-entry" tabindex="-1">Craftsman&#39;s Cheat Sheet (Guidelines for Entry) <a class="header-anchor" href="#craftsman-s-cheat-sheet-guidelines-for-entry" aria-label="Permalink to &quot;Craftsman&#39;s Cheat Sheet (Guidelines for Entry)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Asset Type</th><th style="text-align:left;">Example</th><th style="text-align:left;">Valuation</th><th style="text-align:left;">Lifespan</th><th style="text-align:left;">Mode</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Heavy Machinery</strong></td><td style="text-align:left;"><em>Industrial Clay Mixer</em></td><td style="text-align:left;">Original (actual) price</td><td style="text-align:left;"><code>10–15 years</code></td><td style="text-align:left;">Property</td></tr><tr><td style="text-align:left;"><strong>Molds &amp; Devices</strong></td><td style="text-align:left;"><em>Set of 3 Spherical Steel Molds</em></td><td style="text-align:left;">Actual purchase price</td><td style="text-align:left;"><code>5–10 years</code></td><td style="text-align:left;">Property</td></tr><tr><td style="text-align:left;"><strong>Auxiliary Equipment</strong></td><td style="text-align:left;"><em>Gifted Large Mixing Barrel</em></td><td style="text-align:left;">Estimated market value</td><td style="text-align:left;"><code>10 years</code></td><td style="text-align:left;">Property (Without Cash Flow expense)</td></tr><tr><td style="text-align:left;"><strong>Fast-Wearing Supplies</strong></td><td style="text-align:left;"><em>Mold Release Oil</em></td><td style="text-align:left;">Purchase price + shipping</td><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">Consumables</td></tr></tbody></table><h3 id="practical-scenarios-cases" tabindex="-1">Practical Scenarios (Cases) <a class="header-anchor" href="#practical-scenarios-cases" aria-label="Permalink to &quot;Practical Scenarios (Cases)&quot;">​</a></h3><details class="faq-item"><summary class="faq-summary">Case A: Gratuitous property, findings, and gifts</summary><p><strong>Situation:</strong> Registering an inherited hand tool set ($500) or metal drying racks found in storage ($350).</p><p><strong>Solution:</strong></p><ul><li><strong>Acquisition Date:</strong> Current date (or approximate date received).</li><li><strong>Initial Cost:</strong> $500 (estimated market value today).</li><li><strong>Lifespan:</strong> 10 years.</li><li><strong>Option &quot;Without Cash Flow expense&quot;:</strong> Strictly <strong>enabled</strong>.</li></ul><p><strong>Economic Result:</strong> Workshop capital increases by $500 (business assets grew), while the operation <strong>does not generate an expense in Cash Flow</strong> and leaves cash balances unaffected since no cash payout occurred.</p></details><details class="faq-item"><summary class="faq-summary">Case B: Purchasing new equipment with shipping costs</summary><p><strong>Situation:</strong> You bought a new industrial clay mixer for $4,000 and paid $200 to a freight company for delivery.</p><p><strong>Solution:</strong></p><ul><li><strong>Acquisition Date:</strong> Date of actual purchase.</li><li><strong>Initial Cost:</strong> $4,000.</li><li><strong>Shipping:</strong> $200.</li><li><strong>Lifespan:</strong> 15 years.</li><li><strong>Option &quot;Without Cash Flow expense&quot;:</strong> Disabled.</li></ul><p><strong>Economic Result:</strong> The program logs a $4,200 outflow in Cash Flow (categorized into Equipment and Logistics). The asset is placed on your balance sheet at $4,200, and systematic depreciation begins from that day forward.</p></details><details class="faq-item"><summary class="faq-summary">Case C: Purchasing consumable materials</summary><p><strong>Situation:</strong> Procuring mold release oil ($40) or heavy-duty trash bags ($30).</p><p><strong>Solution:</strong></p><ul><li><strong>Acquisition Date:</strong> Purchase date.</li><li><strong>Initial Cost:</strong> $40.</li><li><strong>Option &quot;Consumable&quot;:</strong> Strictly <strong>enabled</strong> (lifespan field is automatically locked).</li></ul><p><strong>Economic Result:</strong> The full $40 is immediately recognized as an operating expense in Cash Flow. The item appears in the &quot;Consumables&quot; tab and does not generate depreciation, keeping balance calculations clean.</p></details><details class="faq-item"><summary class="faq-summary">Case D: Historical equipment (purchased before using the software)</summary><p><strong>Situation:</strong> You purchased an automatic cutter 3 years ago for $1,500 and want to add it now.</p><p><strong>Solution:</strong></p><ul><li><strong>Acquisition Date:</strong> Historical date (select approximate purchase date 3 years ago in the calendar).</li><li><strong>Initial Cost:</strong> $1,500 (original purchase price).</li><li><strong>Lifespan:</strong> 10 years (total lifespan from purchase).</li><li><strong>Option &quot;Without Cash Flow expense&quot;:</strong> Disabled.</li></ul><p><strong>Economic Result:</strong> The program logs the historical $1,500 investment in Cash Flow. It automatically computes accumulated depreciation for the past 3 years and displays the accurate residual value (approx. $1,050) in your active business Capital.</p></details><hr><h2 id="adding-a-new-asset" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 12h8"></path><path d="M12 8v8"></path></svg> Adding a New Asset <a class="header-anchor" href="#adding-a-new-asset" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;circle cx=&quot;12&quot; cy=&quot;12&quot; r=&quot;10&quot;/&gt;&lt;path d=&quot;M8 12h8&quot;/&gt;&lt;path d=&quot;M12 8v8&quot;/&gt;&lt;/svg&gt; Adding a New Asset&quot;">​</a></h2><p>To add a new item, click the <strong>&quot;Add Asset&quot;</strong> button at the top of the screen.</p><figure class="doc-image"><img src="'+o+'" alt="Modal window for adding a new asset"><figcaption>Modal window for adding a new asset</figcaption></figure><p>The software applies the <strong>valuation start point</strong> principle: if you are entering an older tool acquired prior to using OmniCraft ERP, simply evaluate its current worth as if selling it today and set the approximate remaining lifespan.</p><h3 id="basic-parameters" tabindex="-1">Basic Parameters <a class="header-anchor" href="#basic-parameters" aria-label="Permalink to &quot;Basic Parameters&quot;">​</a></h3><ul><li><strong>Asset Name:</strong> Clear and concise title.</li><li><strong>Acquisition Date:</strong> The exact date the equipment was added to your balance sheet. Defaults to today, but can be backdated to record historical data.</li><li><strong>Category:</strong> Group for structure and reporting (e.g., Equipment, Tools, Premises).</li><li><strong>Initial Cost:</strong> Purchase price (for new items) or current valuation (for older assets). Recorded as an outflow in Cash Flow unless &quot;Without Cash Flow expense&quot; is enabled.</li><li><strong>Shipping:</strong> Additional delivery expenses, automatically logged in Cash Flow under Logistics.</li><li><strong>Lifespan (Years):</strong> Expected service duration. Linear depreciation and residual value tracking begin strictly from the recorded acquisition date.</li></ul><h3 id="special-settings-checkboxes" tabindex="-1">Special Settings (Checkboxes) <a class="header-anchor" href="#special-settings-checkboxes" aria-label="Permalink to &quot;Special Settings (Checkboxes)&quot;">​</a></h3><p>Two checkboxes let you fine-tune the financial logic:</p><div class="tip custom-block"><p class="custom-block-title">&quot;Consumable&quot; Checkbox</p><p>Enable when adding minor tools or workshop supplies. The software locks the lifespan field and assigns the item to the &quot;Consumables&quot; tab. The entire amount is expensed immediately.</p></div><div class="tip custom-block"><p class="custom-block-title">&quot;Without Cash Flow expense&quot; Checkbox</p><p>Enable if the tool was gifted, brought from home, or funded by a targeted grant. The equipment increases business Capital without generating an outflow in Cash Flow.</p></div><h3 id="additional-parameters" tabindex="-1">Additional Parameters <a class="header-anchor" href="#additional-parameters" aria-label="Permalink to &quot;Additional Parameters&quot;">​</a></h3><p>Expand the block at the bottom of the form to configure:</p><ul><li><strong>Inv. Number (Auto):</strong> Leave blank for auto-generated identifiers (<code>INV-XXXX</code>).</li><li><strong>Location:</strong> Physical placement (specific shelf or rack).</li><li><strong>Photo:</strong> Attach an image, automatically compressed to WebP format.</li><li><strong>Link:</strong> Supplier URL or documentation link.</li><li><strong>Notes:</strong> Freeform commentary.</li></ul><hr><h2 id="asset-lifecycle-available-actions" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"></path><path d="M3 3v5h5"></path></svg> Asset Lifecycle &amp; Available Actions <a class="header-anchor" href="#asset-lifecycle-available-actions" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8&quot;/&gt;&lt;path d=&quot;M3 3v5h5&quot;/&gt;&lt;/svg&gt; Asset Lifecycle &amp; Available Actions&quot;">​</a></h2><p>Equipment requires servicing, revaluations, or disposal over time. All actions are accessible via action buttons in table rows.</p><h3 id="asset-profile-interactive-card" tabindex="-1">Asset Profile (Interactive Card) <a class="header-anchor" href="#asset-profile-interactive-card" aria-label="Permalink to &quot;Asset Profile (Interactive Card)&quot;">​</a></h3><p>Clicking any asset name opens its full passport card.</p><figure class="doc-image"><img src="'+a+'" alt="Asset passport card with operations log"><figcaption>Asset passport card with operations log</figcaption></figure><p>It displays photos, specifications, residual value, and an <strong>individual operations log</strong> tracking all historical events for that specific object.</p><h3 id="managing-property" tabindex="-1">Managing Property <a class="header-anchor" href="#managing-property" aria-label="Permalink to &quot;Managing Property&quot;">​</a></h3><ol><li><p><strong>Editing:</strong> Correct titles, update categories, or replace photos.</p></li><li><p><strong>Revaluation &amp; Modernization:</strong> If tool value increases (upgrades or inflation), click <strong>&quot;Revaluate&quot;</strong> in the edit dialog. Set a new book value and remaining lifespan. Depreciation schedules recalculate from the Revaluation Date. If upgrades required paid repairs or parts, enable &quot;Paid service / repair (Cash Flow expense)&quot; to log the cost in Cash Flow.</p><figure class="doc-image"><img src="'+i+'" alt="Asset revaluation modal"><figcaption>Asset revaluation modal</figcaption></figure></li><li><p><strong>Status Changes:</strong> Switch between &quot;Active&quot; and &quot;In Reserve&quot; (temporarily idle).</p></li><li><p><strong>Disposal (Trash icon):</strong> Write off broken or lost assets. Historical Cash Flow transactions are preserved, while total workshop Capital decreases.</p></li></ol><h3 id="managing-consumables" tabindex="-1">Managing Consumables <a class="header-anchor" href="#managing-consumables" aria-label="Permalink to &quot;Managing Consumables&quot;">​</a></h3><ol><li><p><strong>Replenish:</strong> Click the cart icon to top up stock (e.g., buying more paint). Enter purchase price and shipping; amounts are added to total expenditure and logged in Cash Flow.</p><figure class="doc-image"><img src="'+s+'" alt="Consumable replenishment modal"><figcaption>Consumable replenishment modal</figcaption></figure></li><li><p><strong>Archiving:</strong> Move discontinued consumables to archive (box icon) to hide them from active lists. View and restore archived items via the top toolbar button.</p></li></ol><hr><h2 id="workshop-operations-log" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="4" x="8" y="2" rx="1" ry="1"></rect><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><path d="M12 11h4"></path><path d="M12 16h4"></path><path d="M8 11h.01"></path><path d="M8 16h.01"></path></svg> Workshop Operations Log <a class="header-anchor" href="#workshop-operations-log" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;rect width=&quot;8&quot; height=&quot;4&quot; x=&quot;8&quot; y=&quot;2&quot; rx=&quot;1&quot; ry=&quot;1&quot;/&gt;&lt;path d=&quot;M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2&quot;/&gt;&lt;path d=&quot;M12 11h4&quot;/&gt;&lt;path d=&quot;M12 16h4&quot;/&gt;&lt;path d=&quot;M8 11h.01&quot;/&gt;&lt;path d=&quot;M8 16h.01&quot;/&gt;&lt;/svg&gt; Workshop Operations Log&quot;">​</a></h2><p>Click the clock icon in the top toolbar to open the <strong>Operations Log</strong>.</p><p>This chronological registry tracks:</p><ul><li>New asset additions.</li><li>Edits (logging previous and updated values).</li><li>Revaluations, replenishments, archiving, and write-offs.</li></ul><hr><h2 id="search-sorting-filtering" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon></svg> Search, Sorting &amp; Filtering <a class="header-anchor" href="#search-sorting-filtering" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;polygon points=&quot;22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3&quot;/&gt;&lt;/svg&gt; Search, Sorting &amp; Filtering&quot;">​</a></h2><p>Tools for navigating large asset catalogs:</p><ul><li><strong>Search Bar:</strong> Real-time search across titles, inventory numbers, categories, and locations.</li><li><strong>Sorting:</strong> Click any column header (e.g., &quot;Residual&quot; or &quot;Serves until&quot;) to sort ascending or descending.</li><li><strong>Filtering:</strong> Hover over column headers to access multi-select checkboxes for statuses, categories, or locations.</li><li><strong>Quick Reset:</strong> Reset buttons appear above the table whenever filters or sorting are applied.</li></ul><p>Tables feature pagination (30 rows per page) for responsive performance.</p><hr><h2 id="tab-interface-settings" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="4" x2="20" y1="21" y2="14"></line><line x1="4" x2="20" y1="10" y2="3"></line><line x1="12" x2="12" y1="21" y2="12"></line><line x1="12" x2="12" y1="8" y2="3"></line><line x1="8" x2="16" y1="14" y2="14"></line><line x1="8" x2="16" y1="10" y2="10"></line></svg> Tab Interface Settings <a class="header-anchor" href="#tab-interface-settings" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;line x1=&quot;4&quot; x2=&quot;20&quot; y1=&quot;21&quot; y2=&quot;14&quot;/&gt;&lt;line x1=&quot;4&quot; x2=&quot;20&quot; y1=&quot;10&quot; y2=&quot;3&quot;/&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;21&quot; y2=&quot;12&quot;/&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;8&quot; y2=&quot;3&quot;/&gt;&lt;line x1=&quot;8&quot; x2=&quot;16&quot; y1=&quot;14&quot; y2=&quot;14&quot;/&gt;&lt;line x1=&quot;8&quot; x2=&quot;16&quot; y1=&quot;10&quot; y2=&quot;10&quot;/&gt;&lt;/svg&gt; Tab Interface Settings&quot;">​</a></h2><p>Click the <strong>settings (sliders) icon</strong> in the top toolbar to configure:</p><ol><li><strong>Statistics Display:</strong> Toggle between modal popup and pinned sidebar column (auto-hides on compact screens).</li><li><strong>Column Visibility:</strong> Hide unused columns independently for Property and Consumables tables.</li><li><strong>Additional Parameters Visibility:</strong> Toggle optional input fields (locations, URLs, photos) in addition dialogs.</li></ol><p><em>Note: Manage category and location directories by clicking the pencil icon next to dropdown selectors.</em></p><hr><h2 id="workshop-statistics-analytical-block" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" x2="12" y1="20" y2="10"></line><line x1="18" x2="18" y1="20" y2="4"></line><line x1="6" x2="6" y1="20" y2="16"></line></svg> Workshop Statistics (Analytical Block) <a class="header-anchor" href="#workshop-statistics-analytical-block" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;20&quot; y2=&quot;10&quot;/&gt;&lt;line x1=&quot;18&quot; x2=&quot;18&quot; y1=&quot;20&quot; y2=&quot;4&quot;/&gt;&lt;line x1=&quot;6&quot; x2=&quot;6&quot; y1=&quot;20&quot; y2=&quot;16&quot;/&gt;&lt;/svg&gt; Workshop Statistics (Analytical Block)&quot;">​</a></h2><p>Click the analytics icon in the top toolbar to display workshop metrics:</p><ol><li><strong>Residual Asset Value:</strong> Total currency value of all physical assets adjusted for accumulated depreciation.</li><li><strong>Current Monthly Depreciation:</strong> Value reduction of your tool pool every 30 days.</li><li><strong>Capital Structure:</strong> Progress bars showing asset concentration across categories (e.g., Machinery 75%, Tools 25%).</li><li><strong>Tool Pool Summary:</strong> Total item count, active units, and items currently held in reserve.</li></ol><hr><h2 id="frequently-asked-questions-faq" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"></path><path d="M12 17h.01"></path></svg> Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;circle cx=&quot;12&quot; cy=&quot;12&quot; r=&quot;10&quot;/&gt;&lt;path d=&quot;M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3&quot;/&gt;&lt;path d=&quot;M12 17h.01&quot;/&gt;&lt;/svg&gt; Frequently Asked Questions (FAQ)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What if I made a mistake estimating an asset&#39;s lifespan?</summary><div class="faq-content"><p>Depreciation is recalculated dynamically. You can adjust the lifespan at any time using <strong>&quot;Revaluate&quot;</strong> in the asset profile card. Starting from the revaluation date, the software computes wear according to new parameters without distorting past financial history.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I account for market equipment price appreciation?</summary><div class="faq-content"><p>If the market value of your equipment rises, perform a soft revaluation: open the asset profile, click <strong>&quot;Revaluate&quot;</strong>, and enter the updated, higher book value. Your business Capital increases while cash balances remain unaffected, as no physical transaction occurred.</p></div></details><details class="faq-item"><summary class="faq-summary">I lost the purchase receipts for older tools. What price should I enter?</summary><div class="faq-content"><p>This depends on whether business funds (your personal investments) were spent:</p><ul><li><strong>Purchased for the workshop:</strong> Enter the original purchase cost (even approximate) and select the historical purchase date in the calendar. The software records this as an investment in Cash Flow and automatically computes depreciation up to the present.<br><br><em>💡 <strong>Idle equipment tip:</strong> If an asset sat in storage unused and you want depreciation to begin only now, register it with its historical date first, then immediately open its card and perform a <strong>&quot;Revaluation&quot;</strong> using today&#39;s date and the full lifespan.</em></li><li><strong>Gifted or personal property:</strong> Estimate its <em>current fair market value</em> today, set today&#39;s date, specify remaining lifespan, and <strong>strictly enable &quot;Without Cash Flow expense&quot;</strong>.</li></ul></div></details></div>',73)])])}const v=n(c,[["render",d]]);export{k as __pageData,v as default};
